@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap');
:root{--ink:#f7f5e9;--muted:#cad7ce;--gold:#ffdf91;--glass:rgba(9,43,51,.74);--line:rgba(231,241,222,.18)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#287e83;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#227c83;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(6,43,54,.36),transparent 22%,transparent 66%,rgba(9,44,43,.4)),radial-gradient(ellipse at 50% 48%,transparent 40%,rgba(6,43,49,.15) 100%)}.topbar{position:absolute;top:max(22px,env(safe-area-inset-top));left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;z-index:2}.brand{display:flex;gap:11px;align-items:center;text-shadow:0 2px 8px #18434b}.brand-mark{width:37px;height:37px;display:grid;place-items:center;border:1px solid rgba(255,235,179,.75);border-radius:50%;font-size:21px;color:#ffe4a0}.brand strong{display:block;font-size:12px;letter-spacing:2.4px}.brand small{display:block;margin-top:3px;color:#d1ded1;font-size:8px;letter-spacing:1.75px}.day-pill,.icon-button,.glass{background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 12px 35px rgba(5,37,42,.16)}.day-pill{height:38px;border-radius:20px;display:flex;align-items:center;gap:10px;padding:0 14px;font-size:10px;letter-spacing:1px}.day-pill i{height:13px;width:1px;background:#a5bdb4}.sun-icon{font-size:16px;color:#ffdf91}.icon-button{width:38px;height:38px;border-radius:50%;font-size:17px;cursor:pointer}.status-panel{position:absolute;top:102px;left:30px;width:214px;padding:13px 15px;border-radius:12px}.status-title,.inventory-heading{font-size:9px;letter-spacing:1.5px;color:#cad9d0;display:flex;justify-content:space-between;margin-bottom:12px}.status-title span+span{font-size:8px;color:#ecd99c;letter-spacing:.8px}.meter{height:20px;display:flex;align-items:center;gap:8px}.meter-icon{font-size:12px;width:13px;text-align:center}.heart{color:#ff8583}.food{color:#ffda8b}.water{color:#83d7e7}.meter-track,.progress-track{height:5px;border-radius:5px;background:rgba(228,238,222,.17);flex:1;overflow:hidden}.meter-fill{height:100%;width:100%;border-radius:5px;transition:width .25s}.health{background:#ff8d8a}.hunger{background:#ffdc91}.thirst{background:#8cdaea}.meter>b{font-size:9px;font-weight:600;width:21px;text-align:right}.inventory{position:absolute;left:30px;top:235px;width:214px;padding:13px 15px;border-radius:12px}.inventory-heading{margin-bottom:9px}.inventory-heading span{font-size:8px;color:#aac0b7;letter-spacing:.6px}.resource-list>div{height:24px;display:flex;align-items:center;gap:8px;font-size:10px;color:#e5e9d8}.resource-list b{margin-left:auto;color:#fff4ce;font-size:10px}.resource-icon{width:14px;text-align:center;font-size:13px}.wood{color:#d99c67}.stone{color:#c6d1c9}.fiber{color:#9edba3}.berry{color:#f394a0}.quest-card{position:absolute;top:102px;right:30px;width:248px;padding:17px 18px 14px;border-radius:13px}.quest-kicker{font-size:9px;letter-spacing:1.4px;color:#ffdf91}.quest-kicker span{font-size:13px;margin-right:4px}.quest-card h2{font-family:'Playfair Display',serif;font-weight:500;font-size:19px;margin:9px 0 5px}.quest-card p{font-size:10px;line-height:1.55;color:#c5d5cd;margin:0 0 13px}.quest-progress{display:flex;align-items:center;gap:9px;font-size:9px;color:#e6dec1}.progress-track{height:4px}.progress-track div{height:100%;background:#ffdf91;width:0;transition:width .3s}.recipe{border-top:1px solid var(--line);padding-top:10px;margin-top:11px}.recipe>span{display:block;color:#a8c0b5;font-size:8px;letter-spacing:1px;margin-bottom:7px}.recipe>div{display:flex;gap:11px}.recipe b{font-size:10px;font-weight:500;color:#e9dfc2}.recipe i{font-style:normal;color:#fff}.hint-pill{position:absolute;top:51%;left:50%;transform:translate(-50%,-50%);border-radius:20px;padding:8px 14px;font-size:10px;color:#fff2c9;opacity:0;transition:opacity .2s;pointer-events:none;white-space:nowrap}.hint-pill.visible{opacity:1}.bottom-ui{position:absolute;left:30px;right:30px;bottom:max(28px,env(safe-area-inset-bottom));display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.move-control,.quick-actions{pointer-events:auto}.move-control{display:flex;align-items:center;flex-direction:column;gap:6px;color:#d7e5d7;font-size:8px;letter-spacing:1.5px;text-shadow:0 1px 5px #124147;touch-action:none;user-select:none}.joy-ring{position:relative;width:112px;height:112px;background:rgba(9,43,51,.4);border:1px solid rgba(228,244,218,.35);border-radius:50%;box-shadow:inset 0 0 18px #204a4b70,0 8px 22px #143f4770}.joy-ring:before,.joy-ring:after{content:'';position:absolute;background:rgba(227,242,219,.15)}.joy-ring:before{width:1px;height:100%;left:50%}.joy-ring:after{height:1px;width:100%;top:50%}#joy-knob{position:absolute;left:50%;top:50%;width:45px;height:45px;transform:translate(-50%,-50%);border:1px solid rgba(255,246,209,.56);background:rgba(244,239,202,.29);border-radius:50%;box-shadow:0 3px 12px #163f45}.quick-actions{display:flex;align-items:flex-end;gap:9px}.action-button{width:65px;height:67px;padding:7px 4px 6px;border:1px solid rgba(233,242,220,.25);border-radius:12px;background:rgba(9,43,51,.77);backdrop-filter:blur(12px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;box-shadow:0 6px 20px #153d4770;cursor:pointer;transition:transform .15s,background .15s;touch-action:manipulation}.action-button:active{transform:translateY(2px) scale(.97)}.action-button.primary{border-color:rgba(255,223,145,.7);background:rgba(116,89,43,.8);width:74px;height:76px}.action-icon{font-size:18px;color:#ffdf91;line-height:1.15}.action-button b{font-size:8px;letter-spacing:1px}.action-button small{font-size:8px;color:#bfcec3}.help-tip{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);font-size:8px;color:#d6e5d9;text-shadow:0 1px 4px #16494d;display:flex;align-items:center;gap:7px;white-space:nowrap}.help-tip span{padding:3px 5px;border:1px solid #d6e5d966;border-radius:4px;font-size:7px}.toast{position:absolute;left:50%;top:calc(50% + 50px);transform:translate(-50%,10px);padding:10px 16px;border:1px solid #fff4c044;border-radius:22px;background:#143d42e8;font-size:11px;opacity:0;transition:.22s;pointer-events:none;text-align:center;max-width:90%}.toast.show{opacity:1;transform:translate(-50%,0)}.screen-overlay{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:linear-gradient(90deg,rgba(5,38,47,.65),rgba(7,44,49,.12) 76%),linear-gradient(0deg,rgba(4,40,44,.3),transparent 65%);transition:opacity .5s}.screen-overlay.hidden{opacity:0;pointer-events:none}.start-card{width:min(410px,calc(100% - 34px));padding:33px 37px 25px;border-radius:18px;background:rgba(10,48,54,.82);border-color:#e4eedb35;box-shadow:0 24px 70px #042c3466}.island-stamp{width:45px;height:45px;border:1px solid #f3d99688;color:#ffdf91;border-radius:50%;display:grid;place-items:center;font-size:25px;margin-bottom:19px}.eyebrow{font-size:9px;letter-spacing:2.2px;color:#ffdf91;margin:0 0 11px}.start-card h1{font-family:'Playfair Display',serif;font-size:38px;line-height:1.07;font-weight:500;margin:0 0 14px;letter-spacing:-.7px}.start-card h1 em{color:#ffdf91}.intro{font-size:12px;line-height:1.7;color:#d0dfd4;margin:0 0 19px}.start-facts{display:flex;gap:15px;color:#bad0c6;font-size:8px;letter-spacing:.7px;margin-bottom:19px}.start-button{height:43px;width:100%;border:0;border-radius:6px;background:#e6c982;color:#183d3d;font-size:10px;font-weight:700;letter-spacing:1px;display:flex;align-items:center;justify-content:center;gap:17px;cursor:pointer;transition:background .15s}.start-button:hover{background:#f2dda4}.start-button span{font-size:16px}.note{display:block;text-align:center;margin-top:13px;font-size:9px;color:#abc4ba}.screen-decoration{position:absolute;right:30px;bottom:25px;color:#d3dfd299;font-size:8px;letter-spacing:1.7px}.ending-card{max-width:400px}.ending-card h1{font-size:34px}
@media(max-width:700px){.topbar{left:15px;right:15px;top:max(14px,env(safe-area-inset-top))}.brand-mark{width:32px;height:32px}.brand strong{font-size:10px;letter-spacing:1.7px}.brand small{font-size:7px;letter-spacing:1px}.day-pill{height:32px;padding:0 10px;gap:7px;font-size:8px}.icon-button{height:32px;width:32px}.status-panel{top:68px;left:12px;width:160px;padding:9px 11px}.inventory{top:190px;left:12px;width:160px;padding:9px 11px}.status-title{font-size:8px;margin-bottom:7px}.meter{height:17px}.resource-list>div{height:21px;font-size:9px}.inventory-heading{font-size:8px;margin-bottom:5px}.quest-card{top:68px;right:12px;width:min(191px,calc(100% - 184px));padding:11px 12px}.quest-card h2{font-size:15px;margin:6px 0 4px}.quest-card p{font-size:9px;line-height:1.4;margin-bottom:9px}.quest-kicker{font-size:8px}.recipe{padding-top:7px;margin-top:8px}.recipe>div{gap:7px}.recipe b{font-size:8px}.bottom-ui{left:14px;right:14px;bottom:max(18px,env(safe-area-inset-bottom))}.joy-ring{width:92px;height:92px}#joy-knob{width:39px;height:39px}.quick-actions{gap:6px}.action-button{height:59px;width:56px}.action-button.primary{height:68px;width:65px}.help-tip{display:none}.screen-decoration{right:12px;bottom:10px;font-size:7px}.start-card{padding:25px 24px 20px}.start-card h1{font-size:33px}.intro{font-size:11px}.start-facts{gap:9px;font-size:7px}.island-stamp{margin-bottom:14px}.hint-pill{top:49%;font-size:9px}.toast{top:calc(49% + 40px)}}
@media(max-width:390px){.quest-card{width:175px}.status-panel,.inventory{width:145px}.inventory{top:183px}.quest-card p{font-size:8px}.resource-list>div{font-size:8px}.brand small{letter-spacing:.55px}.quick-actions{gap:4px}.action-button{width:51px}.action-button.primary{width:61px}}
@media(max-height:600px) and (min-width:701px){.status-panel{top:80px}.inventory{top:208px}.quest-card{top:80px}.bottom-ui{bottom:12px}.joy-ring{width:88px;height:88px}.action-button{height:58px}.action-button.primary{height:66px}.help-tip{display:none}.start-card{padding:20px 30px}.island-stamp{margin-bottom:10px}.start-card h1{font-size:31px}.intro{margin-bottom:12px}.start-facts{margin-bottom:12px}}

(()=>{'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const ui={day:document.getElementById('day-label'),clock:document.getElementById('clock-label'),health:document.getElementById('health-fill'),hunger:document.getElementById('hunger-fill'),thirst:document.getElementById('thirst-fill'),hv:document.getElementById('health-value'),hu:document.getElementById('hunger-value'),tv:document.getElementById('thirst-value'),wood:document.getElementById('wood-count'),stone:document.getElementById('stone-count'),fiber:document.getElementById('fiber-count'),berry:document.getElementById('berry-count'),cap:document.getElementById('inventory-cap'),progress:document.getElementById('quest-progress-fill'),plabel:document.getElementById('quest-progress-label'),nw:document.getElementById('need-wood'),ns:document.getElementById('need-stone'),nf:document.getElementById('need-fiber'),hint:document.getElementById('hint'),toast:document.getElementById('toast'),interact:document.getElementById('interact-label'),craft:document.getElementById('craft-label'),weather:document.getElementById('weather')};
let W=0,H=0,dpr=1,t=0,last=0,active=false,ended=false,toastTimer=0,soundOn=false,audio=null;
const world={w:1700,h:1200};const player={x:850,y:660,dir:0,moving:false,walk:0,health:100,hunger:100,thirst:100};const inventory={wood:0,stone:0,fiber:0,berry:0};
const keys={};let joy={x:0,y:0};let objects=[];let particles=[];let clouds=[];let dayTime=8;
const rand=(a,b)=>a+Math.random()*(b-a);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function makeWorld(){objects=[];let specs=[['wood',700,470],['wood',1110,630],['wood',600,820],['wood',1260,820],['wood',930,950],['stone',560,600],['stone',1070,430],['stone',1250,690],['stone',770,900],['fiber',830,390],['fiber',1180,520],['fiber',480,750],['fiber',1020,870],['berry',660,550],['berry',1040,740],['berry',870,1020],['berry',1320,590],['beacon',1380,390],['spring',600,440],['shelter',760,725]];for(let [type,x,y] of specs)objects.push({type,x,y,found:false,phase:rand(0,7)});for(let i=0;i<36;i++)clouds.push({x:rand(-200,world.w+200),y:rand(-100,world.h+100),r:rand(24,65),speed:rand(2,8),alpha:rand(.08,.2)})}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize,{passive:true});resize();makeWorld();
function project(x,y){return{x:W/2+(x-player.x)*.83,y:H*.53+(y-player.y)*.48}}function worldPoint(sx,sy){return{x:player.x+(sx-W/2)/.83,y:player.y+(sy-H*.53)/.48}}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function drawGround(){ctx.fillStyle='#25828a';ctx.fillRect(0,0,W,H);let center=project(850,600);let scale=.83;ctx.save();ctx.translate(center.x,center.y);ctx.scale(scale,scale*.58);let rad=0;ctx.beginPath();for(let i=0;i<=120;i++){let a=i/120*Math.PI*2;let jitter=1+Math.sin(a*7+.7)*.035+Math.sin(a*13)*.02;let rx=725*jitter,ry=480*jitter;let x=Math.cos(a)*rx,y=Math.sin(a)*ry;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();ctx.fillStyle='#d5c28d';ctx.fill();ctx.strokeStyle='#e7d8a6';ctx.lineWidth=28;ctx.stroke();ctx.beginPath();for(let i=0;i<=120;i++){let a=i/120*Math.PI*2;let jitter=1+Math.sin(a*7+.7)*.035+Math.sin(a*13)*.02;let x=Math.cos(a)*686*jitter,y=Math.sin(a)*444*jitter;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();let g=ctx.createLinearGradient(-400,-350,500,400);g.addColorStop(0,'#83ad76');g.addColorStop(.55,'#699765');g.addColorStop(1,'#4e8060');ctx.fillStyle=g;ctx.fill();ctx.restore();
// shallow turquoise reef foam
ctx.save();ctx.globalAlpha=.16;for(let i=0;i<26;i++){let a=i*.243+t*.015;let p=project(850+Math.cos(a)*760,600+Math.sin(a)*490);ellipse(p.x,p.y,rand(10,26),rand(3,8),'#fff4d0')}ctx.restore();
// beach drift lines and grass patches
for(let i=0;i<36;i++){let x=160+(i*137)%1380,y=120+(i*223)%960;let dx=x-850,dy=y-600;if((dx*dx)/(710*710)+(dy*dy)/(470*470)<.8){let p=project(x,y);ctx.strokeStyle='rgba(228,211,157,.16)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.quadraticCurveTo(p.x+12,p.y-4,p.x+27,p.y-1);ctx.stroke()}}
}
function drawWater(){ctx.save();for(const c of clouds){c.x+=c.speed*.008;if(c.x>world.w+280)c.x=-200;let p=project(c.x,c.y);ctx.globalAlpha=c.alpha;ellipse(p.x,p.y,c.r,c.r*.35,'#c7e9d8')}ctx.restore();for(let i=0;i<28;i++){let xx=((i*197+t*7)% (W+160))-80,yy=H*.25+((i*71)%Math.max(1,H*.64));ctx.strokeStyle=`rgba(195,241,221,${.09+Math.sin(t+i)*.04})`;ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(xx,yy);ctx.quadraticCurveTo(xx+15,yy-3,xx+31,yy);ctx.stroke()}}
function drawPalm(x,y,s=1,lean=0){let p=project(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ellipse(0,2,18,6,'#355e4d');ctx.strokeStyle='#7d6040';ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(lean,-25,lean*.7,-66);ctx.stroke();ctx.strokeStyle='#a28457';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-2,0);ctx.quadraticCurveTo(lean-2,-30,lean*.7-2,-64);ctx.stroke();let cx=lean*.7,cy=-67;for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.fillStyle=i%2?'#347b58':'#40895d';ctx.beginPath();ctx.moveTo(cx,cy);ctx.quadraticCurveTo(cx+Math.cos(a)*25-5,cy+Math.sin(a)*13-23,cx+Math.cos(a)*55,cy+Math.sin(a)*31);ctx.quadraticCurveTo(cx+Math.cos(a)*27+7,cy+Math.sin(a)*15+5,cx,cy);ctx.fill();ctx.strokeStyle='#82a76a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx+Math.cos(a)*49,cy+Math.sin(a)*27);ctx.stroke()}ellipse(cx,cy,7,5,'#b48655');ctx.restore()}
function drawObject(o){let p=project(o.x,o.y);if(o.found&&o.type!=='beacon'&&o.type!=='spring'&&o.type!=='shelter')return;let bob=Math.sin(t*2+o.phase)*2;ctx.save();ctx.translate(p.x,p.y+bob);if(o.type==='wood'){ellipse(0,4,19,7,'#325947');ctx.save();ctx.rotate(-.25);ctx.fillStyle='#946744';ctx.beginPath();ctx.roundRect(-15,-8,29,12,5);ctx.fill();ctx.fillStyle='#c39865';ellipse(12,-2,4,5,'#c39865');ctx.restore();ctx.strokeStyle='#b9cc9b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(3,-21);ctx.stroke()}
else if(o.type==='stone'){ellipse(0,4,19,7,'#355a4d');ctx.fillStyle='#8c9a8d';ctx.beginPath();ctx.moveTo(-15,3);ctx.lineTo(-9,-12);ctx.lineTo(1,-19);ctx.lineTo(15,-9);ctx.lineTo(18,3);ctx.closePath();ctx.fill();ctx.strokeStyle='#c4cec0';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-9,-12);ctx.lineTo(1,-5);ctx.lineTo(15,-9);ctx.stroke()}
else if(o.type==='fiber'){ellipse(0,5,16,6,'#416148');for(let i=0;i<5;i++){ctx.strokeStyle=['#7fb978','#91c27d','#6d9d6c'][i%3];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8+i*4,4);ctx.quadraticCurveTo(-15+i*8,-10,-6+i*4,-19);ctx.stroke()}}
else if(o.type==='berry'){ellipse(0,5,18,6,'#416148');ctx.fillStyle='#4b8c5c';ctx.beginPath();ctx.ellipse(0,-5,12,10,0,0,Math.PI*2);ctx.fill();for(let i=0;i<5;i++)ellipse(-7+i*4,-8+(i%2)*7,2.4,2.4,'#e9818a');ctx.strokeStyle='#8fbd75';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-13);ctx.lineTo(1,-19);ctx.stroke()}
else if(o.type==='beacon'){ellipse(0,7,27,9,'#34594c');ctx.fillStyle='#ad9a77';ctx.fillRect(-13,-49,26,54);ctx.fillStyle='#e8dfbf';ctx.fillRect(-10,-44,20,45);ctx.fillStyle='#875e48';ctx.fillRect(-15,-54,30,7);ctx.fillStyle='#d8a75e';ctx.beginPath();ctx.moveTo(-17,-54);ctx.lineTo(0,-71);ctx.lineTo(17,-54);ctx.closePath();ctx.fill();ctx.fillStyle='#b9e8dc';ctx.fillRect(-5,-38,10,12);ctx.fillStyle='#534d42';ctx.fillRect(-3,-34,6,8);ctx.fillStyle='#f7d88e';ctx.beginPath();ctx.arc(0,-43,3,0,Math.PI*2);ctx.fill();if(inRange(o)){ctx.globalAlpha=.13+Math.sin(t*3)*.06;ellipse(0,-42,45,37,'#ffe9a8')} }
else if(o.type==='spring'){ellipse(0,4,23,9,'#356555');ellipse(0,0,17,8,'#62b9b0');ellipse(0,-2,12,5,'#a9ded1');ctx.strokeStyle='#e7d5a5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,21,Math.PI,0);ctx.stroke()}
else if(o.type==='shelter'){ellipse(0,7,30,8,'#395e4c');ctx.fillStyle='#a5784b';ctx.beginPath();ctx.moveTo(-26,0);ctx.lineTo(0,-37);ctx.lineTo(26,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d1ad73';ctx.beginPath();ctx.moveTo(-20,-1);ctx.lineTo(0,-31);ctx.lineTo(20,-1);ctx.closePath();ctx.fill();ctx.fillStyle='#624b39';ctx.fillRect(-5,-2,10,9)}
if(active&&near(o)&&!o.found&&o.type!=='beacon'&&o.type!=='spring'&&o.type!=='shelter'){ctx.strokeStyle='#ffdf91';ctx.lineWidth=1.5;ctx.setLineDash([3,3]);ctx.beginPath();ctx.ellipse(0,0,24,16,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}
function drawCharacter(){let p=project(player.x,player.y);let bob=player.moving?Math.sin(player.walk)*2.7:Math.sin(t*1.6)*.8;ctx.save();ctx.translate(p.x,p.y+bob);ellipse(0,4,16,6,'#3b5f4e'); // shadow
// legs
ctx.strokeStyle='#f0bd9b';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-4,-9);ctx.lineTo(-5,-1);ctx.moveTo(4,-9);ctx.lineTo(5,-1);ctx.stroke();ctx.fillStyle='#e9cfab';ctx.beginPath();ctx.ellipse(-6,0,5,2.4,0,0,Math.PI*2);ctx.ellipse(6,0,5,2.4,0,0,Math.PI*2);ctx.fill();
// tasteful survival wrap tunic
