function inRange(o){return Math.hypot(o.x-player.x,o.y-player.y)<60}function near(o){return Math.hypot(o.x-player.x,o.y-player.y)<75}function nearest(){let found=null,d=Infinity;for(const o of objects){if(o.found||!['wood','stone','fiber','berry','beacon','spring','shelter'].includes(o.type))continue;let n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){found=o;d=n}}return d<78?found:null}
