let sorted=[...objects].sort((a,b)=>a.y-b.y);for(let o of sorted)drawObject(o);drawCharacter();drawAmbient();}
function drawAmbient(){for(let i=0;i<10;i++){let x=(i*173+t*11)%(W+60)-30,y=H*.2+((i*91+Math.sin(t+i)*19)%(H*.65));ctx.fillStyle=`rgba(255,244,197,${.14+Math.sin(t*2+i)*.08})`;ctx.beginPath();ctx.arc(x,y,1.3,0,Math.PI*2);ctx.fill()}}

function update(dt){t+=dt;dayTime+=dt*.035;if(dayTime>=20){dayTime=6}let sx=keys.d||keys.arrowright?1:0,sx2=keys.a||keys.arrowleft?-1:0,sy=keys.s||keys.arrowdown?1:0,sy2=keys.w||keys.arrowup?-1:0;let mx=sx+sx2+joy.x,my=sy+sy2+joy.y;let mag=Math.hypot(mx,my);player.moving=mag>.12;if(player.moving){mx/=Math.max(1,mag);my/=Math.max(1,mag);player.x=clamp(player.x+mx*145*dt,150,1550);player.y=clamp(player.y+my*145*dt,130,1070);player.walk+=dt*12;player.dir=Math.atan2(my,mx)}if(active){player.hunger=Math.max(0,player.hunger-dt*.24);player.thirst=Math.max(0,player.thirst-dt*.34);if(player.hunger<=0||player.thirst<=0)player.health=Math.max(0,player.health-dt*1.3);if(player.health<=0)player.health=50,player.hunger=65,player.thirst=65,showToast('You rest beneath the palms and feel a little better.')}updateUI();const n=nearest();if(n){ui.hint.textContent=hintFor(n);ui.hint.classList.add('visible');ui.interact.textContent=actionFor(n)}else{ui.hint.classList.remove('visible');ui.interact.textContent='Explore'}}
function hintFor(o){return o.type==='beacon'?'Old beacon · interact to repair':o.type==='spring'?'Freshwater spring · drink to restore thirst':o.type==='shelter'?'Your shelter · rest and recover':`Gather ${o.type==='wood'?'driftwood':o.type==='stone'?'stone':o.type==='fiber'?'vine fiber':'island fruit'}`}
function actionFor(o){return o.type==='beacon'?'Repair':o.type==='spring'?'Drink':o.type==='shelter'?'Rest':'Gather'}
function updateUI(){let vals=[player.health,player.hunger,player.thirst];[ui.health,ui.hunger,ui.thirst].forEach((el,i)=>el.style.width=`${vals[i]}%`);[ui.hv,ui.hu,ui.tv].forEach((el,i)=>el.textContent=Math.round(vals[i]));ui.wood.textContent=inventory.wood;ui.stone.textContent=inventory.stone;ui.fiber.textContent=inventory.fiber;ui.berry.textContent=inventory.berry;let count=Object.values(inventory).reduce((a,b)=>a+b,0);ui.cap.textContent=`${count} / 24`;ui.nw.textContent=inventory.wood;ui.ns.textContent=inventory.stone;ui.nf.textContent=inventory.fiber;let goal=Math.min(13,Math.min(inventory.wood,6)+Math.min(inventory.stone,4)+Math.min(inventory.fiber,3));ui.progress.style.width=`${goal/13*100}%`;ui.plabel.textContent=`${goal} / 13`;ui.day.textContent='DAY 1';let h=Math.floor(dayTime),m=Math.floor((dayTime-h)*60);ui.clock.textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;ui.weather.textContent=dayTime>17?'GOLDEN HOUR':'CLEAR SKIES';document.getElementById('craft-label').textContent=objects.find(o=>o.type==='shelter')?.found?'Rest':'Shelter'}
function showToast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}function bump(){if(soundOn){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=560;g.gain.value=.03;o.start();o.stop(audio.currentTime+.07)}catch(e){}}}
function doInteract(){if(!active)return;let o=nearest();if(!o){showToast('Wander the island to find useful supplies.');return}bump();if(o.type==='beacon'){if(inventory.wood>=6&&inventory.stone>=4&&inventory.fiber>=3){inventory.wood-=6;inventory.stone-=4;inventory.fiber-=3;ended=true;document.getElementById('end-screen').classList.remove('hidden');showToast('The beacon is shining!')}else showToast(`The beacon needs ${Math.max(0,6-inventory.wood)} wood, ${Math.max(0,4-inventory.stone)} stone & ${Math.max(0,3-inventory.fiber)} fiber.`);return}if(o.type==='spring'){player.thirst=Math.min(100,player.thirst+42);showToast('Cool, clear water. Thirst restored.');return}if(o.type==='shelter'){player.health=Math.min(100,player.health+15);player.hunger=Math.min(100,player.hunger+8);player.thirst=Math.min(100,player.thirst+8);showToast('A quiet rest beneath your shelter.');return}if(Object.values(inventory).reduce((a,b)=>a+b,0)>=24){showToast('Your backpack is full.');return}o.found=true;inventory[o.type]++;let names={wood:'Driftwood',stone:'Stone',fiber:'Vine fiber',berry:'Island fruit'};showToast(`${names[o.type]} gathered.`);updateUI()}
function eat(){if(!active)return;if(inventory.berry<1){showToast('Find some island fruit first.');return}inventory.berry--;player.hunger=Math.min(100,player.hunger+32);player.health=Math.min(100,player.health+3);bump();showToast('Sweet island fruit. You feel better.');updateUI()}
function craft(){if(!active)return;let shelter=objects.find(o=>o.type==='shelter');if(shelter.found){showToast('Your little shelter is a good place to rest.');return}if(inventory.wood<3||inventory.fiber<2){showToast('Shelter needs 3 driftwood and 2 vine fiber.');return}inventory.wood-=3;inventory.fiber-=2;shelter.found=true;showToast('A simple shelter—somewhere safe to rest.');bump();updateUI()}
function reset(){player.x=850;player.y=660;player.health=100;player.hunger=100;player.thirst=100;dayTime=8;for(let k in inventory)inventory[k]=0;makeWorld();ended=false;document.getElementById('end-screen').classList.add('hidden');document.getElementById('start-screen').classList.remove('hidden');updateUI()}
function start(){active=true;document.getElementById('start-screen').classList.add('hidden');showToast('Explore the island. Supplies sparkle when you are close.');last=performance.now();requestAnimationFrame(frame)}function frame(now){if(!active)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
document.getElementById('start-button').addEventListener('click',start);document.getElementById('interact-button').addEventListener('click',doInteract);document.getElementById('eat-button').addEventListener('click',eat);document.getElementById('craft-button').addEventListener('click',craft);document.getElementById('play-again').addEventListener('click',reset);document.getElementById('sound-toggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.classList.toggle('on',soundOn);e.currentTarget.textContent=soundOn?'♪':'♫';if(soundOn)bump()});
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'||k===' ')doInteract();if(k==='f')eat();if(k==='c')craft()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
const joyEl=document.getElementById('joystick'),knob=document.getElementById('joy-knob');let pointer=null;joyEl.addEventListener('pointerdown',e=>{pointer=e.pointerId;joyEl.setPointerCapture(pointer);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(pointer===e.pointerId)joyMove(e)});function joyMove(e){let r=joyEl.querySelector('.joy-ring').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),lim=r.width*.33,d=Math.hypot(dx,dy);if(d>lim){dx*=lim/d;dy*=lim/d}joy.x=dx/lim;joy.y=dy/lim;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}function endJoy(){pointer=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}joyEl.addEventListener('pointerup',endJoy);joyEl.addEventListener('pointercancel',endJoy);
// Initial painted world and passive animation preview
function preview(){if(active)return;t+=.008;draw();requestAnimationFrame(preview)}updateUI();requestAnimationFrame(preview);
})();

