(()=>{'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const ui={day:document.getElementById('day-label'),clock:document.getElementById('clock-label'),health:document.getElementById('health-fill'),hunger:document.getElementById('hunger-fill'),thirst:document.getElementById('thirst-fill'),hv:document.getElementById('health-value'),hu:document.getElementById('hunger-value'),tv:document.getElementById('thirst-value'),wood:document.getElementById('wood-count'),stone:document.getElementById('stone-count'),fiber:document.getElementById('fiber-count'),berry:document.getElementById('berry-count'),cap:document.getElementById('inventory-cap'),progress:document.getElementById('quest-progress-fill'),plabel:document.getElementById('quest-progress-label'),nw:document.getElementById('need-wood'),ns:document.getElementById('need-stone'),nf:document.getElementById('need-fiber'),hint:document.getElementById('hint'),toast:document.getElementById('toast'),interact:document.getElementById('interact-label'),craft:document.getElementById('craft-label'),weather:document.getElementById('weather')};
let W=0,H=0,dpr=1,t=0,last=0,active=false,ended=false,toastTimer=0,soundOn=false,audio=null;
const world={w:1700,h:1200};const player={x:850,y:660,dir:0,moving:false,walk:0,health:100,hunger:100,thirst:100};const inventory={wood:0,stone:0,fiber:0,berry:0};const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
let objects=[],clouds=[],dayTime=8;const keys={},joy={x:0,y:0};
function makeWorld(){objects=[];for(let [type,x,y] of [['wood',700,470],['wood',1110,630],['wood',600,820],['wood',1260,820],['wood',930,950],['stone',560,600],['stone',1070,430],['stone',1250,690],['stone',770,900],['fiber',830,390],['fiber',1180,520],['fiber',480,750],['fiber',1020,870],['berry',660,550],['berry',1040,740],['berry',870,1020],['berry',1320,590],['beacon',1380,390],['spring',600,440],['shelter',760,725]])objects.push({type,x,y,found:false,phase:rand(0,7)});clouds=[];for(let i=0;i<36;i++)clouds.push({x:rand(-200,world.w+200),y:rand(-100,world.h+100),r:rand(24,65),speed:rand(2,8),alpha:rand(.08,.2)})}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize,{passive:true});resize();makeWorld();
function project(x,y){return{x:W/2+(x-player.x)*.83,y:H*.53+(y-player.y)*.48}}function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
