');ellipse(0,-2,12,5,'#a9ded1');ctx.strokeStyle='#e7d5a5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,21,Math.PI,0);ctx.stroke()}else if(o.type==='shelter'){ellipse(0,7,30,8,'#395e4c');ctx.fillStyle='#a5784b';ctx.beginPath();ctx.moveTo(-26,0);ctx.lineTo(0,-37);ctx.lineTo(26,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d1ad73';ctx.beginPath();ctx.moveTo(-20,-1);ctx.lineTo(0,-31);ctx.lineTo(20,-1);ctx.closePath();ctx.fill();ctx.fillStyle='#624b39';ctx.fillRect(-5,-2,10,9)}if(active&&near(o)&&!o.found&&o.type!=='beacon'&&o.type!=='spring'&&o.type!=='shelter'){ctx.strokeStyle='#ffdf91';ctx.lineWidth=1.5;ctx.setLineDash([3,3]);ctx.beginPath();ctx.ellipse(0,0,24,16,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}
function drawCharacter(){let p=project(player.x,player.y),bob=player.moving?Math.sin(player.walk)*2.7:Math.sin(t*1.6)*.8;ctx.save();ctx.translate(p.x,p.y+bob);ellipse(0,4,16,6,'#3b5f4e');ctx.strokeStyle='#f0bd9b';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-4,-9);ctx.lineTo(-5,-1);ctx.moveTo(4,-9);ctx.lineTo(5,-1);ctx.stroke();ctx.fillStyle='#e9cfab';ctx.beginPath();ctx.ellipse(-6,0,5,2.4,0,0,Math.PI*2);ctx.ellipse(6,0,5,2.4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5b987';ctx.beginPath();ctx.moveTo(-9,-23);ctx.quadraticCurveTo(-12,-13,-10,-7);ctx.quadraticCurveTo(0,-3,10,-7);ctx.quadraticCurveTo(12,-15,8,-23);ctx.closePath();ctx.fill();ctx.strokeStyle='#f0d9a8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-18);ctx.lineTo(8,-18);ctx.stroke();ctx.strokeStyle='#f0bd9b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-8,-21);ctx.lineTo(-12,-12);ctx.moveTo(8,-21);ctx.lineTo(12,-13);ctx.stroke();ctx.fillStyle='#f4c9ac';ctx.beginPath();ctx.ellipse(0,-30,8,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#493539';ctx.beginPath();ctx.ellipse(0,-35,9,8,0,Math.PI,Math.PI*2);ctx.lineTo(8,-29);ctx.quadraticCurveTo(5,-34,2,-33);ctx.quadraticCurveTo(-4,-28,-8,-31);ctx.closePath();ctx.fill();ctx.fillStyle='#61403b';ctx.beginPath();ctx.moveTo(-6,-34);ctx.quadraticCurveTo(-14,-29,-10,-20);ctx.quadraticCurveTo(-9,-25,-7,-27);ctx.fill();ctx.beginPath();ctx.moveTo(7,-34);ctx.quadraticCurveTo(14,-28,9,-19);ctx.quadraticCurveTo(7,-24,7,-28);ctx.fill();ellipse(-2,-30,1,1,'#51403b');ellipse(2,-30,1,1,'#51403b');ctx.strokeStyle='#b87f78';ctx.lineWidth=.8;ctx.beginPath();ctx.arc(0,-27,2,0,Math.PI);ctx.stroke();ctx.restore()}
