function doInteract(){if(!active)return;let o=nearest();if(!o){showToast('Wander the island to find useful supplies.');return}bump();if(o.type==='beacon'){if(inventory.wood>=6&&inventory.stone>=4&&inventory.fiber>=3){inventory.wood-=6;inventory.stone-=4;inventory.fiber-=3;ended=true;document.getElementById('end-screen').classList.remove('hidden');showToast('The beacon is shining!')}else showToast(`The beacon needs ${Math.max(0,6-inventory.wood)} wood, ${Math.max(0,4-inventory.stone)} stone & ${Math.max(0,3-inventory.fiber)} fiber.`);return}if(o.type==='spring'){player.thirst=Math.min(100,player.thirst+42);showToast('Cool, clear water. Thirst restored.');return}if(o.type==='shelter'){player.health=Math.min(100,player.health+15);player.hunger=Math.min(100,player.hunger+8);player.thirst=Math.min(100,player.thirst+8);showToast('A quiet rest beneath your shelter.');return}if(Object.values(inventory).reduce((a,b)=>a+b,0)>=24){showToast('Your backpack is full.');return}o.found=true;inventory[o.type]++;showToast(`${{wood:'Driftwood',stone:'Stone',fiber:'Vine fiber',berry:'Island fruit'}[o.type]} gathered.`);updateUI()}

function eat(){if(!active)return;if(inventory.berry<1){showToast('Find some island fruit first.');return}inventory.berry--;player.hunger=Math.min(100,player.hunger+32);player.health=Math.min(100,player.health+3);bump();showToast('Sweet island fruit. You feel better.');updateUI()}function craft(){if(!active)return;let shelter=objects.find(o=>o.type==='shelter');if(shelter.found){showToast('Your little shelter is a good place to rest.');return}if(inventory.wood<3||inventory.fiber<2){showToast('Shelter needs 3 driftwood and 2 vine fiber.');return}inventory.wood-=3;inventory.fiber-=2;shelter.found=true;showToast('A simple shelter—somewhere safe to rest.');bump();updateUI()}
