const $=id=>document.getElementById(id),ui={day:$('day-label'),clock:$('clock-label'),health:$('health-fill'),hunger:$('hunger-fill'),thirst:$('thirst-fill'),hv:$('health-value'),hu:$('hunger-value'),tv:$('thirst-value'),wood:$('wood-count'),stone:$('stone-count'),fiber:$('fiber-count'),berry:$('berry-count'),cap:$('inventory-cap'),progress:$('quest-progress-fill'),plabel:$('quest-progress-label'),nw:$('need-wood'),ns:$('need-stone'),nf:$('need-fiber'),hint:$('hint'),toast:$('toast'),interact:$('interact-label'),weather:$('weather')};
